// Bounded, copied metadata projection. No output paths or native pointers cross JS.
emscripten::val jcad_dwg_export_metadata_wrapper(uintptr_t dwg_ptr,
                                                uint32_t max_bytes) {
  emscripten::val result = emscripten::val::object();
  emscripten::val objects = emscripten::val::array();
  emscripten::val notes = emscripten::val::array();
  result.set("schemaVersion", 1);
  result.set("dxf", std::string());
  result.set("objects", objects);
  result.set("writeError", DWG_ERR_IOERROR);
  result.set("complete", false);
  result.set("notes", notes);
  if (!dwg_ptr || !max_bytes || max_bytes > 32u * 1024u * 1024u) {
    notes.call<void>("push", std::string("Invalid native metadata projection limit."));
    return result;
  }
  Dwg_Data* dwg = reinterpret_cast<Dwg_Data*>(dwg_ptr);
  if (dwg->num_objects > 100000) {
    notes.call<void>("push", std::string("Native object inventory exceeds the 100000-record limit."));
    return result;
  }
  bool inventory_complete = true;
  for (BITCODE_BL i = 0; i < dwg->num_objects; i++) {
    const Dwg_Object* obj = &dwg->object[i];
    if (!obj->handle.value) {
      inventory_complete = false;
      continue;
    }
    const char* name = obj->name ? obj->name : "UNKNOWN";
    const char* dxfname = obj->dxfname ? obj->dxfname : name;
    if (strnlen(name, 257) > 256 || strnlen(dxfname, 257) > 256) {
      inventory_complete = false;
      continue;
    }
    char handle[17];
    std::snprintf(handle, sizeof(handle), "%llX",
                  static_cast<unsigned long long>(obj->handle.value));
    emscripten::val item = emscripten::val::object();
    item.set("handle", std::string(handle));
    item.set("type", std::string(name));
    item.set("dxfType", std::string(dxfname));
    item.set("supertype", std::string(
      obj->supertype == DWG_SUPERTYPE_ENTITY ? "entity" :
      obj->supertype == DWG_SUPERTYPE_OBJECT ? "object" : "unknown"));
    objects.call<void>("push", item);
    if (obj->fixedtype == DWG_TYPE_UNKNOWN_ENT ||
        obj->fixedtype == DWG_TYPE_UNKNOWN_OBJ ||
        (obj->supertype != DWG_SUPERTYPE_ENTITY &&
         obj->supertype != DWG_SUPERTYPE_OBJECT))
      inventory_complete = false;
  }
  if (!inventory_complete)
    notes.call<void>("push", std::string("Some native objects have no complete DXF projection identity."));
#ifdef DISABLE_DXF
  result.set("writeError", DWG_ERR_NOTYETSUPPORTED);
  notes.call<void>("push", std::string("This native runtime does not include DXF projection."));
  return result;
#else
  // A fixed memory stream stops writes at the limit, before MEMFS can grow.
  // The extra byte permits an exact-limit output and its terminating NUL.
  std::unique_ptr<char, decltype(&free)> buffer(
    static_cast<char*>(calloc(static_cast<size_t>(max_bytes) + 1u, 1)), &free);
  if (!buffer) {
    result.set("writeError", DWG_ERR_OUTOFMEM);
    notes.call<void>("push", std::string("Native metadata projection allocation failed."));
    return result;
  }
  FILE* stream = fmemopen(buffer.get(), static_cast<size_t>(max_bytes) + 1u, "w");
  if (!stream) {
    notes.call<void>("push", std::string("Native metadata projection stream could not be opened."));
    return result;
  }
  Bit_Chain dat = {};
  dat.version = dwg->header.version;
  dat.from_version = dwg->header.from_version;
  dat.codepage = dwg->header.codepage;
  dat.fh = stream;
  const int native_error = dwg_write_dxf(&dat, dwg);
  const int flush_error = fflush(stream);
  const long length = ftell(stream);
  const bool stream_error = ferror(stream) != 0;
  const int close_error = fclose(stream);
  const bool over_limit = length < 0 ||
    static_cast<unsigned long>(length) > max_bytes;
  const int write_error = native_error |
    ((flush_error || stream_error || close_error || over_limit)
      ? DWG_ERR_IOERROR : 0);
  result.set("writeError", write_error);
  if (write_error) {
    notes.call<void>("push", std::string(over_limit || stream_error
      ? "Native metadata projection exceeded its output limit or failed to write."
      : "Native metadata DXF projection returned an error."));
    return result;
  }
  result.set("dxf", std::string(buffer.get(), static_cast<size_t>(length)));
  // This is only the native projection's precondition. The app must reconcile
  // every source inventory identity against DXF records before retaining a graph:
  // LibreDWG's top-level exporter does not propagate every skipped-class flag.
  result.set("complete", inventory_complete);
  notes.call<void>("push", std::string("Source inventory and DXF graph coverage must be reconciled."));
  return result;
#endif
}

